import * as React from "react"
import { InView } from "@/components/primitives/in-view"

import { cn } from "@/lib/utils"
import { Button } from "@/components/ui/button"

// ═══ JOB         Mega accordion — large expandable rows with inline media.
// ═══ EMOTION     Editorial + a media reward.
// ═══ SIGNATURE   Big rows that expand to reveal an image + copy; open row auto-collapses.

export type MegaRow = { id: string; title: string; body?: string; src?: string; meta?: string }

export type InteractiveAccordionMegaProps = {
  eyebrow?: string
  title?: React.ReactNode
  rows: MegaRow[]
  tone?: "paper" | "ink"
  className?: string
}

const DEFAULT_ROWS = [
  { id: "m1", title: "Design", body: "Drawn full-scale before anything is cut.", src: "/showcase/content/content-04-architecture.webp", meta: "chapter 01" },
  { id: "m2", title: "Build", body: "One maker per piece, start to finish.", src: "/showcase/content/content-05-workshop.webp", meta: "chapter 02" },
  { id: "m3", title: "Care", body: "Annual check-up included, forever.", src: "/showcase/gallery-06.webp", meta: "chapter 03" },
]
export function InteractiveAccordionMega({ eyebrow = "MEGA", title = "Rows worth opening.", rows = DEFAULT_ROWS, tone = "paper", className }: InteractiveAccordionMegaProps) {
  const ink = tone === "ink"
  const [openId, setOpenId] = React.useState<string | null>(rows[0]?.id ?? null)
  const active = rows.find((r) => r.id === openId)
  return (
    <section className={cn("relative isolate w-full overflow-hidden", tone === 'ink' && "bg-foreground", className)}>
  <span aria-hidden className={cn("pointer-events-none absolute bottom-0 left-1/2 w-full max-w-[var(--shell-w)] -translate-x-1/2 border-b border-dashed", tone === 'ink' ? "border-background/10" : "border-border")} />
  <div className={cn("relative mx-auto w-full px-4 sm:px-6 lg:px-8", "py-20 sm:py-24")} style={{ maxWidth: (920), ["--shell-w" as string]: `${(920)}px` }}>

      <InView once variants={{ hidden: { opacity: 0, y: 12 }, visible: { opacity: 1, y: 0 } }} transition={{ duration: 0.8, ease: [0.16, 1, 0.3, 1] }}>
          <header className={cn("relative")}>
    {eyebrow && <span className={cn("mb-5 inline-flex items-center gap-2 font-mono text-[11px] font-bold uppercase tracking-[0.18em]", tone === 'ink' ? "text-background/55" : "text-muted-foreground")}><span aria-hidden className="inline-block size-[5px] rotate-45 bg-current" />{eyebrow}</span>}
    <h2 className={cn("font-display text-[34px] font-black leading-[0.98] tracking-[-0.035em] sm:text-[44px] lg:text-[52px]", tone === 'ink' ? "text-background" : "text-foreground")}>{title}</h2>
  </header>
      </InView>
      <InView once variants={{ hidden: { opacity: 0, y: 16 }, visible: { opacity: 1, y: 0 } }} transition={{ duration: 0.8, ease: [0.16, 1, 0.3, 1], delay: 0.06 }}>
        <div className="mt-10 space-y-3">
          {rows.map((r) => {
            const open = r.id === openId
            return (
              <div key={r.id} className={cn("overflow-hidden rounded-xl border transition-colors", open && (ink ? "border-background/30 bg-background/5" : "border-foreground bg-card"))}>
                <Button type='button' onClick={() => setOpenId(open ? null : r.id)} aria-expanded={open} className="flex h-auto w-full items-center justify-between gap-4 p-6 text-left" variant="ghost">
                  <div className="flex items-baseline gap-4">
                    <span className={cn("font-mono text-[11px] font-bold tracking-[0.2em]", ink ? "text-background/45" : "text-muted-foreground")}>{r.meta ?? "0" + (rows.indexOf(r) + 1)}</span>
                    <h3 className="font-display text-2xl font-bold sm:text-3xl">{r.title}</h3>
                  </div>
                  <span className={cn("shrink-0 font-mono text-xl", open ? "rotate-45" : "", ink ? "text-background/60" : "text-muted-foreground")}>+</span>
                </Button>
                <div className={cn("grid transition-[grid-template-rows] duration-300", open ? "grid-rows-[1fr]" : "grid-rows-[0fr]")}>
                  <div className="overflow-hidden">
                    <div className="grid gap-4 px-6 pb-6 sm:grid-cols-[1fr_auto]">
                      {r.body && <p className={cn("max-w-lg text-sm font-medium leading-relaxed", ink ? "text-background/75" : "text-muted-foreground")}>{r.body}</p>}
                      {r.src && <img src={r.src} alt="" className="aspect-[16/9] w-full max-w-[220px] rounded-xl object-cover" loading="lazy" />}
                    </div>
                  </div>
                </div>
              </div>
            )
          })}
          {active && null}
        </div>
      </InView>

  </div>
</section>
  )
}

/**
 * interactive-accordion-mega — vendored from the UI Engine preset library (axiestudio).
 * Install: npx shadcn@latest add https://axiestudio.github.io/UI_Engine/registry/r/interactive-accordion-mega.json
 * Source of truth: UI/ — do not edit vendored copies blindly.
 */
/**
 * Vendored verbatim from motion-primitives by ibelick (MIT): components/core/accordion.tsx
 */
'use client';
import type { Transition, Variants, Variant } from 'motion/react';
import { motion, AnimatePresence, MotionConfig } from 'motion/react';
import { cn } from '@/lib/utils';
import * as React from 'react';
import { createContext, useContext, useState } from 'react';
import type { ReactNode } from 'react';

export type AccordionContextType = {
  expandedValue: React.Key | null;
  toggleItem: (value: React.Key) => void;
  variants?: { expanded: Variant; collapsed: Variant };
};

const AccordionContext = createContext<AccordionContextType | undefined>(
  undefined
);

function useAccordion() {
  const context = useContext(AccordionContext);
  if (!context) {
    throw new Error('useAccordion must be used within an AccordionProvider');
  }
  return context;
}

export type AccordionProviderProps = {
  children: ReactNode;
  variants?: { expanded: Variant; collapsed: Variant };
  expandedValue?: React.Key | null;
  onValueChange?: (value: React.Key | null) => void;
};

function AccordionProvider({
  children,
  variants,
  expandedValue: externalExpandedValue,
  onValueChange,
}: AccordionProviderProps) {
  const [internalExpandedValue, setInternalExpandedValue] =
    useState<React.Key | null>(null);

  const expandedValue =
    externalExpandedValue !== undefined
      ? externalExpandedValue
      : internalExpandedValue;

  const toggleItem = (value: React.Key) => {
    const newValue = expandedValue === value ? null : value;
    if (onValueChange) {
      onValueChange(newValue);
    } else {
      setInternalExpandedValue(newValue);
    }
  };

  return (
    <AccordionContext.Provider value={{ expandedValue, toggleItem, variants }}>
      {children}
    </AccordionContext.Provider>
  );
}

export type AccordionProps = {
  children: ReactNode;
  className?: string;
  transition?: Transition;
  variants?: { expanded: Variant; collapsed: Variant };
  expandedValue?: React.Key | null;
  onValueChange?: (value: React.Key | null) => void;
};

function Accordion({
  children,
  className,
  transition,
  variants,
  expandedValue,
  onValueChange,
}: AccordionProps) {
  return (
    <MotionConfig transition={transition}>
      <div className={cn('relative', className)} aria-orientation='vertical'>
        <AccordionProvider
          variants={variants}
          expandedValue={expandedValue}
          onValueChange={onValueChange}
        >
          {children}
        </AccordionProvider>
      </div>
    </MotionConfig>
  );
}

export type AccordionItemProps = {
  value: React.Key;
  children: ReactNode;
  className?: string;
};

function AccordionItem({ value, children, className }: AccordionItemProps) {
  const { expandedValue } = useAccordion();
  const isExpanded = value === expandedValue;

  return (
    <div
      className={cn('overflow-hidden', className)}
      {...(isExpanded ? { 'data-expanded': '' } : {'data-closed': ''})}
    >
      {React.Children.map(children, (child) => {
        if (React.isValidElement(child)) {
          return React.cloneElement(
            child,
            { value, expanded: isExpanded } as Record<string, unknown>,
          );
        }
        return child;
      })}
    </div>
  );
}

export type AccordionTriggerProps = {
  children: ReactNode;
  className?: string;
};

function AccordionTrigger({
  children,
  className,
  ...props
}: AccordionTriggerProps) {
  const { toggleItem, expandedValue } = useAccordion();
  const value = (props as { value?: React.Key }).value;
  const isExpanded = value === expandedValue;

  return (
    <button
      onClick={() => value !== undefined && toggleItem(value)}
      aria-expanded={isExpanded}
      type='button'
      className={cn('group', className)}
      {...(isExpanded ? { 'data-expanded': '' } : {'data-closed': ''})}
    >
      {children}
    </button>
  );
}

export type AccordionContentProps = {
  children: ReactNode;
  className?: string;
};

function AccordionContent({
  children,
  className,
  ...props
}: AccordionContentProps) {
  const { expandedValue, variants } = useAccordion();
  const value = (props as { value?: React.Key }).value;
  const isExpanded = value === expandedValue;

  const BASE_VARIANTS: Variants = {
    expanded: { height: 'auto', opacity: 1 },
    collapsed: { height: 0, opacity: 0 },
  };

  const combinedVariants = {
    expanded: { ...BASE_VARIANTS.expanded, ...variants?.expanded },
    collapsed: { ...BASE_VARIANTS.collapsed, ...variants?.collapsed },
  };

  return (
    <AnimatePresence initial={false}>
      {isExpanded && (
        <motion.div
          initial='collapsed'
          animate='expanded'
          exit='collapsed'
          variants={combinedVariants}
          className={className}
        >
          {children}
        </motion.div>
      )}
    </AnimatePresence>
  );
}

export { Accordion, AccordionItem, AccordionTrigger, AccordionContent };

